    [InlineData(20_000, LoyaltyTier.Gold, 2_500, 17_500)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_500, 27_500)]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, tier, "WELCOME5", expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(1_500, Handle(10_000, LoyaltyTier.Silver, code).DiscountCents);

